from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="200" viewBox="0 0 680 200" role="img">\n<title>City skyline — 3D city</title><desc>isometric blocks breathe</desc>\n<style>@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}} @keyframes breathe{0%,100%{opacity:.6}50%{opacity:1}} .win{animation:breathe 1.6s infinite} .bld{transform-origin:bottom;animation:grow .6s forwards;transform:scaleY(0)} @keyframes grow{to{transform:scaleY(1)}}</style>\n<rect width="680" height="200" rx="16" fill="#020617"/>\n<text x="20" y="28" fill="#e2e8f0" font-family="monospace" font-size="12">CONTRIBUTION CITY — 3D skyline</text>\n<g transform="translate(20,50)">\n  <path d="M0 90 L 420 30 L 640 90 L 220 150 Z" fill="#1e293b" stroke="#334155"/>\n  <g class="bld" style="animation-delay:.0s" transform="translate(0,0)"><rect x="0" y="50" width="36" height="40" fill="#22c55e"/><rect x="4" y="54" width="6" height="6" rx="1" fill="#fef08a" class="win"/></g>\n  <g class="bld" style="animation-delay:.08s" transform="translate(46,0)"><rect x="0" y="40" width="36" height="50" fill="#16a34a"/><rect x="4" y="44" width="6" height="6" rx="1" fill="#fef08a" class="win" style="animation-delay:.2s"/></g>\n  <g class="bld" style="animation-delay:.16s" transform="translate(92,0)"><rect x="0" y="30" width="36" height="60" fill="#15803d"/><rect x="4" y="34" width="6" height="6" rx="1" fill="#fef08a" class="win"/></g>\n  <g class="bld" style="animation-delay:.24s" transform="translate(138,0)"><rect x="0" y="50" width="36" height="40" fill="#4ade80"/><rect x="4" y="54" width="6" height="6" rx="1" fill="#fef08a" class="win"/></g>\n  <g class="bld" style="animation-delay:.32s" transform="translate(184,0)"><rect x="0" y="35" width="36" height="55" fill="#86efac"/><rect x="4" y="39" width="6" height="6" rx="1" fill="#fef08a" class="win"/></g>\n  <g class="bld" style="animation-delay:.40s" transform="translate(230,0)"><rect x="0" y="45" width="36" height="45" fill="#22c55e"/><rect x="4" y="49" width="6" height="6" rx="1" fill="#fef08a" class="win"/></g>\n</g>\n</svg>\n'
Path(__file__).resolve().parents[2].joinpath('assets','city-skyline.svg').write_text(svg, encoding='utf-8')
